const META_KEY = /^(?:__proto__|constructor|prototype)$/;

function safeParseQuery(query: string): Record<string, unknown> {
  const out: Record<string, unknown> = Object.create(null); // ✅ không thừa hưởng gì
  for (const [key, value] of new URLSearchParams(query)) {
    const path = key.split('[').map((s) => s.replace(']', ''));
    if (path.some((step) => META_KEY.test(step))) continue; // ✅ drop + log, không gán
    let cursor: any = out;
    for (const step of path.slice(0, -1)) cursor = cursor[step] ??= {};
